              unidad: "EUR",
              etiqueta: "Cuota del mínimo personal y familiar",
              formula: "Suma de cuotas por tramo del mínimo",
            }),
          ],
          fuentes: [
            {
              titulo: "Parámetros IRPF estatal 2012-2026",
